class Solution {
    public int minMalwareSpread(int[][] graph,int[] initial){
        int n=graph.length;
        int[] parent=new int[n],size=new int[n];
        for(int i=0;i<n;i++){
            parent[i]=i;
            size[i]=1;
        }
        for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)if(graph[i][j]==1)union(i,j,parent,size);
        int[] infected=new int[n];
        for(int node:initial)infected[find(node,parent)]++;
        Arrays.sort(initial);
        int answer=initial[0],best=-1;
        for(int node:initial){
            int root=find(node,parent),saved=infected[root]==1?size[root]:0;
            if(saved>best){
                best=saved;
                answer=node;
            }
        }
        return answer;
    }
    private int find(int x,int[] p){
        return p[x]==x?x:(p[x]=find(p[x],p));
    }
    private void union(int a,int b,int[] p,int[] s){
        a=find(a,p);
        b=find(b,p);
        if(a==b)return;
        if(s[a]<s[b]){
            int t=a;
            a=b;
            b=t;
        }
        p[b]=a;
        s[a]+=s[b];
    }
}

