class Solution {
    fun minMalwareSpread(graph:Array<IntArray>,initial:IntArray):Int{
        val n=graph.size;
        val parent=IntArray(n){
            it
        };
        val size=IntArray(n){
            1
        };
        fun find(xInput:Int):Int{
            var x=xInput;
            while(parent[x]!=x){
                parent[x]=parent[parent[x]];
                x=parent[x]
            };
            return x
        };
        fun union(aInput:Int,bInput:Int){
            var a=find(aInput);
            var b=find(bInput);
            if(a==b)return;
            if(size[a]<size[b]){
                val t=a;
                a=b;
                b=t
            };
            parent[b]=a;
            size[a]+=size[b]
        };
        for(i in 0 until n)for(j in i+1 until n)if(graph[i][j]==1)union(i,j);
        val infected=IntArray(n);
        for(node in initial)infected[find(node)]++;
        initial.sort();
        var answer=initial[0];
        var best=-1;
        for(node in initial){
            val root=find(node);
            val saved=if(infected[root]==1)size[root] else 0;
            if(saved>best){
                best=saved;
                answer=node
            }
        };
        return answer
    }
}

