class Solution {
    vector<int> parent,size;
    int find(int x){
        return parent[x]==x?x:parent[x]=find(parent[x]);
    }
    void unite(int a,int b){
        a=find(a);
        b=find(b);
        if(a==b)return;
        if(size[a]<size[b])swap(a,b);
        parent[b]=a;
        size[a]+=size[b];
    }
    public:int minMalwareSpread(vector<vector<int>>& graph,vector<int>& initial){
        int n=graph.size();
        parent.resize(n);
        iota(parent.begin(),parent.end(),0);
        size.assign(n,1);
        for(int i=0;i<n;++i)for(int j=i+1;j<n;++j)if(graph[i][j])unite(i,j);
        vector<int> infected(n);
        for(int node:initial)++infected[find(node)];
        sort(initial.begin(),initial.end());
        int answer=initial[0],best=-1;
        for(int node:initial){
            int root=find(node),saved=infected[root]==1?size[root]:0;
            if(saved>best){
                best=saved;
                answer=node;
            }
        }
        return answer;
    }
};
